#![cfg(feature = "test")]

//! A router that receives a declaration from a router it cannot identify closes that router's
//! transport, so that the new connection sends every identity and declaration again.

use std::{any::Any, sync::Arc, time::Duration};

use tokio::sync::watch;
use zenoh_core::ztimeout;
use zenoh_link::Link;
use zenoh_protocol::{
    core::{WhatAmI, ZenohIdProto},
    network::{
        declare::{
            self, queryable::ext::QueryableInfoType, DeclareBody, DeclareQueryable,
            DeclareSubscriber, DeclareToken,
        },
        Declare, NetworkBody, NetworkMessage, NetworkMessageMut,
    },
};
use zenoh_result::ZResult;
use zenoh_test::get_free_tcp_port;
use zenoh_transport::{
    multicast::TransportMulticast, unicast::TransportUnicast, TransportEventHandler,
    TransportManager, TransportMulticastEventHandler, TransportPeer, TransportPeerEventHandler,
};

const TIMEOUT: Duration = Duration::from_secs(10);

/// A fake router's transport handler: it ignores what it receives and records `closed()`.
struct FakeRouter(Arc<watch::Sender<bool>>);

impl TransportEventHandler for FakeRouter {
    fn new_unicast(
        &self,
        _peer: TransportPeer,
        _transport: TransportUnicast,
    ) -> ZResult<Arc<dyn TransportPeerEventHandler>> {
        Ok(Arc::new(FakeRouterPeer(self.0.clone())))
    }

    fn new_multicast(
        &self,
        _transport: TransportMulticast,
    ) -> ZResult<Arc<dyn TransportMulticastEventHandler>> {
        panic!();
    }
}

#[derive(Debug)]
struct FakeRouterPeer(Arc<watch::Sender<bool>>);

impl TransportPeerEventHandler for FakeRouterPeer {
    fn handle_message(&self, _message: NetworkMessageMut) -> ZResult<()> {
        Ok(())
    }

    fn new_link(&self, _link: Link) {}
    fn del_link(&self, _link: Link) {}

    fn closed(&self) {
        self.0.send_replace(true);
    }

    fn as_any(&self) -> &dyn Any {
        self
    }
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_declaration_from_a_router_that_never_named_itself_closes_its_transport() {
    zenoh::init_log_from_env_or("error");
    let endpoint = format!("tcp/127.0.0.1:{}", get_free_tcp_port());
    let mut config = zenoh::Config::default();
    config.insert_json5("mode", r#""router""#).unwrap();
    config
        .insert_json5("listen/endpoints", &format!(r#"["{endpoint}"]"#))
        .unwrap();
    config
        .insert_json5("scouting/multicast/enabled", "false")
        .unwrap();
    let router = ztimeout!(zenoh::open(config)).unwrap();

    let declarations = [
        (
            "a subscriber",
            DeclareBody::DeclareSubscriber(DeclareSubscriber {
                id: 1,
                wire_expr: "test/unidentified".into(),
            }),
        ),
        (
            "a queryable",
            DeclareBody::DeclareQueryable(DeclareQueryable {
                id: 1,
                wire_expr: "test/unidentified".into(),
                ext_info: QueryableInfoType::DEFAULT,
            }),
        ),
        (
            "a token",
            DeclareBody::DeclareToken(DeclareToken {
                id: 1,
                wire_expr: "test/unidentified".into(),
            }),
        ),
    ];
    for (what, body) in declarations {
        // A router with a fresh identity, which never sends a linkstate naming itself.
        let closed = Arc::new(watch::Sender::new(false));
        let fake = TransportManager::builder()
            .whatami(WhatAmI::Router)
            .zid(ZenohIdProto::rand())
            .build_test(Arc::new(FakeRouter(closed.clone())))
            .unwrap();
        let transport = ztimeout!(fake.open_transport_unicast(endpoint.parse().unwrap())).unwrap();

        // A declaration that names its router by a node id the link never mapped.
        let mut message = NetworkMessage::from(NetworkBody::Declare(Declare {
            interest_id: None,
            ext_qos: declare::ext::QoSType::DECLARE,
            ext_tstamp: None,
            ext_nodeid: declare::ext::NodeIdType { node_id: 7 },
            body,
        }));
        assert!(transport.schedule(message.as_mut()).unwrap());

        tokio::time::timeout(TIMEOUT, closed.subscribe().wait_for(|closed| *closed))
            .await
            .unwrap_or_else(|_| panic!("{what} from an unidentified router closed its transport"))
            .unwrap();
        ztimeout!(fake.close());
    }

    ztimeout!(router.close()).unwrap();
}
